<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Leap Studio — Your Reinvention and Experience Partner</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg: #0A0A0A;
  --bg-card: #141414;
  --bg-card-hover: #1A1A1A;
  --white: #FFFFFF;
  --gray-100: #F5F5F5;
  --gray-300: #D4D4D4;
  --gray-400: #A3A3A3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --accent: #3B82F6;
  --accent-hover: #2563EB;
  --amber: #F59E0B;
  --amber-hover: #D97706;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font);
  background: var(--bg);
  color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: none; background: none; color: inherit; }
img { display: block; max-width: 100%; }

/* ===== UTILITY ===== */
.container { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
@media (min-width: 768px) { .container { padding: 0 48px; } }
.accent { color: var(--accent); }
.amber { color: var(--amber); }

/* ===== NAVIGATION ===== */
.nav {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  background: rgba(10, 10, 10, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.nav__inner {
  display: flex; align-items: center; justify-content: space-between;
  height: 72px; max-width: 1280px; margin: 0 auto; padding: 0 24px;
}
.nav__logo { font-weight: 800; font-size: 1.25rem; letter-spacing: -0.03em; }
.nav__logo span { color: var(--accent); }
.nav__links { display: none; gap: 32px; align-items: center; list-style: none; }
@media (min-width: 1024px) { .nav__links { display: flex; } }
.nav__links a {
  font-size: 0.875rem; font-weight: 500; color: var(--gray-400);
  transition: color var(--transition); letter-spacing: 0.01em;
}
.nav__links a:hover { color: var(--white); }
.nav__right { display: flex; align-items: center; gap: 16px; }

/* Language Selector */
.lang-selector { position: relative; }
.lang-selector__btn {
  display: flex; align-items: center; gap: 6px;
  font-size: 0.8rem; font-weight: 500; color: var(--gray-400);
  padding: 6px 12px; border: 1px solid var(--gray-700); border-radius: 6px;
  transition: all var(--transition);
}
.lang-selector__btn:hover { color: var(--white); border-color: var(--gray-500); }
.lang-selector__btn svg { width: 14px; height: 14px; transition: transform var(--transition); }
.lang-selector.open .lang-selector__btn svg { transform: rotate(180deg); }
.lang-selector__dropdown {
  position: absolute; top: calc(100% + 8px); right: 0;
  background: var(--bg-card); border: 1px solid var(--gray-700); border-radius: 8px;
  padding: 6px; min-width: 160px; opacity: 0; visibility: hidden;
  transform: translateY(-8px); transition: all var(--transition);
  box-shadow: 0 16px 48px rgba(0,0,0,0.5);
}
.lang-selector.open .lang-selector__dropdown { opacity: 1; visibility: visible; transform: translateY(0); }
.lang-selector__option {
  display: block; width: 100%; text-align: left; padding: 10px 14px;
  font-size: 0.85rem; color: var(--gray-400); border-radius: 6px;
  transition: all var(--transition);
}
.lang-selector__option:hover, .lang-selector__option.active { color: var(--white); background: var(--gray-800); }

/* Mobile Menu */
.nav__mobile-btn { display: flex; flex-direction: column; gap: 5px; padding: 8px; }
@media (min-width: 1024px) { .nav__mobile-btn { display: none; } }
.nav__mobile-btn span { display: block; width: 22px; height: 2px; background: var(--white); transition: all var(--transition); border-radius: 1px; }
.nav__mobile-btn.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav__mobile-btn.open span:nth-child(2) { opacity: 0; }
.nav__mobile-btn.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }
.mobile-menu {
  display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0;
  background: rgba(10,10,10,0.98); z-index: 99; padding: 32px 24px;
  flex-direction: column; gap: 24px;
}
.mobile-menu.open { display: flex; }
.mobile-menu a { font-size: 1.5rem; font-weight: 600; color: var(--gray-300); transition: color var(--transition); }
.mobile-menu a:hover { color: var(--white); }

/* ===== HERO CAROUSEL ===== */
.hero {
  padding-top: 72px; min-height: 100vh; display: flex; align-items: center;
  position: relative; overflow: hidden;
}
.hero__bg-gradient {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(59,130,246,0.08) 0%, transparent 60%),
              radial-gradient(ellipse at 70% 80%, rgba(245,158,11,0.05) 0%, transparent 50%);
  pointer-events: none;
}
.hero__inner { position: relative; width: 100%; max-width: 1280px; margin: 0 auto; padding: 64px 24px; }
@media (min-width: 768px) { .hero__inner { padding: 80px 48px; } }

.hero__carousel { position: relative; overflow: hidden; }
.hero__track { display: flex; transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1); }
.hero__slide {
  min-width: 100%; display: grid; gap: 40px; align-items: center;
  grid-template-columns: 1fr;
}
@media (min-width: 768px) { .hero__slide { grid-template-columns: 1fr 1fr; } }

.hero__content { padding-right: 20px; }
.hero__tag {
  display: inline-block; font-size: 0.75rem; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.12em; color: var(--accent); margin-bottom: 16px;
  padding: 4px 12px; border: 1px solid rgba(59,130,246,0.3); border-radius: 20px;
}
.hero__title {
  font-size: clamp(2rem, 5vw, 3.5rem); font-weight: 800; line-height: 1.1;
  letter-spacing: -0.03em; margin-bottom: 20px;
}
.hero__desc {
  font-size: 1.1rem; color: var(--gray-400); line-height: 1.7;
  margin-bottom: 32px; max-width: 480px;
}
.hero__cta {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 14px 28px; background: var(--white); color: var(--bg);
  font-weight: 600; font-size: 0.9rem; border-radius: 8px;
  transition: all var(--transition);
}
.hero__cta:hover { background: var(--gray-100); transform: translateY(-1px); box-shadow: 0 8px 24px rgba(255,255,255,0.1); }
.hero__cta svg { width: 16px; height: 16px; transition: transform var(--transition); }
.hero__cta:hover svg { transform: translateX(3px); }

.hero__visual {
  position: relative; aspect-ratio: 4/3; border-radius: 16px; overflow: hidden;
  background: var(--bg-card);
}
.hero__visual-img {
  width: 100%; height: 100%; object-fit: cover;
  background: linear-gradient(135deg, #1a1a2e, #16213e, #0f3460);
  display: flex; align-items: center; justify-content: center;
}
.hero__visual-placeholder {
  width: 100%; height: 100%;
  background: linear-gradient(135deg, var(--bg-card), var(--gray-800));
  display: flex; align-items: center; justify-content: center;
}
.hero__visual-placeholder svg { width: 80px; height: 80px; opacity: 0.15; }

/* Carousel Controls */
.hero__controls {
  display: flex; align-items: center; gap: 16px; margin-top: 48px;
}
.hero__dots { display: flex; gap: 8px; }
.hero__dot {
  width: 32px; height: 4px; border-radius: 2px; background: var(--gray-700);
  transition: all var(--transition); cursor: pointer;
}
.hero__dot.active { width: 48px; background: var(--accent); }
.hero__arrows { display: flex; gap: 8px; margin-left: auto; }
.hero__arrow {
  width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--gray-700);
  display: flex; align-items: center; justify-content: center;
  transition: all var(--transition);
}
.hero__arrow:hover { border-color: var(--gray-500); background: var(--gray-800); }
.hero__arrow svg { width: 18px; height: 18px; }

/* ===== TEAM CAROUSEL ===== */
.team { padding: 120px 0; position: relative; }
.team__bg-accent {
  position: absolute; top: 0; right: -200px; width: 600px; height: 600px;
  background: radial-gradient(circle, rgba(59,130,246,0.04), transparent 70%);
  pointer-events: none;
}
.section-label {
  font-size: 0.75rem; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.15em; color: var(--accent); margin-bottom: 12px;
}
.section-title {
  font-size: clamp(2rem, 4vw, 3rem); font-weight: 800;
  letter-spacing: -0.03em; line-height: 1.15; margin-bottom: 16px;
}
.section-subtitle {
  font-size: 1.1rem; color: var(--gray-400); max-width: 560px; line-height: 1.7;
}

.team__region-tabs {
  display: flex; gap: 4px; margin-top: 48px; margin-bottom: 40px;
  border-bottom: 1px solid var(--gray-800); padding-bottom: 0;
  overflow-x: auto; -ms-overflow-style: none; scrollbar-width: none;
}
.team__region-tabs::-webkit-scrollbar { display: none; }
.team__region-tab {
  padding: 14px 24px; font-size: 0.9rem; font-weight: 500;
  color: var(--gray-500); border-bottom: 2px solid transparent;
  transition: all var(--transition); white-space: nowrap;
  margin-bottom: -1px;
}
.team__region-tab:hover { color: var(--gray-300); }
.team__region-tab.active { color: var(--white); border-bottom-color: var(--accent); }

.team__carousel { position: relative; overflow: hidden; }
.team__track { display: flex; transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1); gap: 20px; }
.team__card {
  min-width: calc(50% - 10px); flex-shrink: 0;
  background: var(--bg-card); border: 1px solid var(--gray-800); border-radius: 16px;
  overflow: hidden; transition: all var(--transition);
}
@media (max-width: 640px) { .team__card { min-width: 85%; } }
@media (min-width: 1024px) { .team__card { min-width: calc(33.333% - 14px); } }
.team__card:hover { border-color: var(--gray-700); transform: translateY(-4px); box-shadow: 0 16px 48px rgba(0,0,0,0.3); }

.team__card-img {
  aspect-ratio: 1; background: linear-gradient(135deg, var(--gray-800), var(--gray-700));
  position: relative; overflow: hidden;
}
.team__card-img-placeholder {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  background: linear-gradient(145deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
}
.team__card-img-placeholder svg { width: 64px; height: 64px; opacity: 0.2; }

.team__card-body { padding: 24px; }
.team__card-name { font-size: 1.1rem; font-weight: 700; margin-bottom: 4px; }
.team__card-title { font-size: 0.85rem; color: var(--gray-400); margin-bottom: 16px; }
.team__card-quote {
  font-size: 0.9rem; color: var(--gray-300); line-height: 1.7;
  font-style: italic; margin-bottom: 20px; padding-left: 16px;
  border-left: 2px solid var(--accent);
}
.team__card-cta {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 0.85rem; font-weight: 500; color: var(--accent);
  transition: all var(--transition);
}
.team__card-cta:hover { color: var(--accent-hover); gap: 12px; }
.team__card-cta svg { width: 14px; height: 14px; }

.team__carousel-controls { display: flex; gap: 8px; margin-top: 32px; justify-content: flex-end; }
.team__carousel-arrow {
  width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--gray-700);
  display: flex; align-items: center; justify-content: center;
  transition: all var(--transition);
}
.team__carousel-arrow:hover { border-color: var(--gray-500); background: var(--gray-800); }
.team__carousel-arrow svg { width: 18px; height: 18px; }

/* ===== WORK SHOWCASE ===== */
.work { padding: 120px 0; }
.work__carousel { position: relative; overflow: hidden; margin-top: 48px; }
.work__track { display: flex; transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1); gap: 20px; }
.work__card {
  min-width: 85%; flex-shrink: 0; border-radius: 16px; overflow: hidden;
  background: var(--bg-card); border: 1px solid var(--gray-800);
  transition: all var(--transition);
}
@media (min-width: 768px) { .work__card { min-width: calc(50% - 10px); } }
@media (min-width: 1024px) { .work__card { min-width: calc(33.333% - 14px); } }
.work__card:hover { border-color: var(--gray-700); transform: translateY(-4px); box-shadow: 0 16px 48px rgba(0,0,0,0.3); }

.work__card-img {
  aspect-ratio: 16/10; position: relative; overflow: hidden;
}
.work__card-img-placeholder {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
}
.work__card-img-placeholder svg { width: 48px; height: 48px; opacity: 0.2; }

.work__card-body { padding: 24px; }
.work__card-client { font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.1em; color: var(--accent); margin-bottom: 8px; }
.work__card-title { font-size: 1.15rem; font-weight: 700; line-height: 1.3; margin-bottom: 12px; }
.work__card-quote { font-size: 0.85rem; color: var(--gray-400); line-height: 1.6; font-style: italic; }
.work__card-quote-author { color: var(--gray-500); font-style: normal; margin-top: 8px; display: block; font-size: 0.8rem; }

.work__carousel-controls { display: flex; gap: 8px; margin-top: 32px; justify-content: flex-end; }
.work__carousel-arrow {
  width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--gray-700);
  display: flex; align-items: center; justify-content: center; transition: all var(--transition);
}
.work__carousel-arrow:hover { border-color: var(--gray-500); background: var(--gray-800); }
.work__carousel-arrow svg { width: 18px; height: 18px; }

/* ===== CTA BANNER ===== */
.cta-banner {
  padding: 100px 0; position: relative; overflow: hidden;
  background: linear-gradient(135deg, rgba(59,130,246,0.08), rgba(245,158,11,0.05));
  border-top: 1px solid var(--gray-800); border-bottom: 1px solid var(--gray-800);
}
.cta-banner__inner { text-align: center; max-width: 640px; margin: 0 auto; }
.cta-banner__title {
  font-size: clamp(2rem, 4vw, 3rem); font-weight: 800; letter-spacing: -0.03em;
  line-height: 1.15; margin-bottom: 20px;
}
.cta-banner__desc { font-size: 1.1rem; color: var(--gray-400); line-height: 1.7; margin-bottom: 36px; }
.cta-banner__btn {
  display: inline-flex; align-items: center; gap: 10px;
  padding: 16px 32px; background: var(--white); color: var(--bg);
  font-weight: 600; font-size: 0.95rem; border-radius: 8px; transition: all var(--transition);
}
.cta-banner__btn:hover { background: var(--gray-100); transform: translateY(-1px); box-shadow: 0 8px 24px rgba(255,255,255,0.1); }
.cta-banner__btn svg { width: 16px; height: 16px; }

/* ===== HOW WE WORK ===== */
.how { padding: 120px 0; }
.how__grid { display: grid; gap: 48px; align-items: center; margin-top: 48px; }
@media (min-width: 768px) { .how__grid { grid-template-columns: 1fr 1fr; } }
.how__visual {
  aspect-ratio: 4/3; border-radius: 16px; overflow: hidden;
  background: linear-gradient(135deg, #1a1a2e, #16213e, #0f3460);
  display: flex; align-items: center; justify-content: center;
}
.how__visual svg { width: 80px; height: 80px; opacity: 0.15; }
.how__content-title {
  font-size: clamp(1.75rem, 3.5vw, 2.5rem); font-weight: 800;
  letter-spacing: -0.03em; line-height: 1.15; margin-bottom: 20px;
}
.how__content-desc { font-size: 1.05rem; color: var(--gray-400); line-height: 1.7; margin-bottom: 32px; }
.how__content-cta {
  display: inline-flex; align-items: center; gap: 10px;
  font-weight: 600; font-size: 0.9rem; color: var(--accent);
  transition: all var(--transition);
}
.how__content-cta:hover { color: var(--accent-hover); gap: 14px; }
.how__content-cta svg { width: 16px; height: 16px; }

/* ===== INSIGHTS ===== */
.insights { padding: 120px 0; }
.insights__grid {
  display: grid; gap: 20px; margin-top: 48px;
  grid-template-columns: 1fr;
}
@media (min-width: 640px) { .insights__grid { grid-template-columns: 1fr 1fr; } }
@media (min-width: 1024px) { .insights__grid { grid-template-columns: 1fr 1fr 1fr; } }

.insight-card {
  background: var(--bg-card); border: 1px solid var(--gray-800); border-radius: 16px;
  overflow: hidden; transition: all var(--transition);
}
.insight-card:hover { border-color: var(--gray-700); transform: translateY(-4px); box-shadow: 0 16px 48px rgba(0,0,0,0.3); }
.insight-card__img {
  aspect-ratio: 16/10; overflow: hidden;
  background: linear-gradient(135deg, var(--gray-800), var(--gray-700));
  display: flex; align-items: center; justify-content: center;
}
.insight-card__img svg { width: 40px; height: 40px; opacity: 0.2; }
.insight-card__body { padding: 20px; }
.insight-card__type {
  display: inline-block; font-size: 0.7rem; font-weight: 600; text-transform: uppercase;
  letter-spacing: 0.1em; padding: 4px 10px; border-radius: 4px; margin-bottom: 12px;
}
.insight-card__type--podcast { background: rgba(59,130,246,0.15); color: var(--accent); }
.insight-card__type--article { background: rgba(245,158,11,0.15); color: var(--amber); }
.insight-card__type--report { background: rgba(16,185,129,0.15); color: #10B981; }
.insight-card__title { font-size: 1rem; font-weight: 600; line-height: 1.4; margin-bottom: 12px; }
.insight-card__cta {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: 0.85rem; font-weight: 500; color: var(--accent); transition: all var(--transition);
}
.insight-card__cta:hover { gap: 10px; }
.insight-card__cta svg { width: 14px; height: 14px; }

/* ===== PRINCIPLES ===== */
.principles { padding: 120px 0; border-top: 1px solid var(--gray-800); }
.principles__grid { display: grid; gap: 24px; margin-top: 48px; }
@media (min-width: 768px) { .principles__grid { grid-template-columns: 1fr 1fr; } }

.principle-card {
  padding: 36px; background: var(--bg-card); border: 1px solid var(--gray-800);
  border-radius: 16px; transition: all var(--transition);
}
.principle-card:hover { border-color: var(--gray-700); }
.principle-card__number {
  font-size: 3rem; font-weight: 900; color: var(--gray-800); line-height: 1; margin-bottom: 16px;
}
.principle-card__title { font-size: 1.25rem; font-weight: 700; margin-bottom: 12px; }
.principle-card__desc { font-size: 0.95rem; color: var(--gray-400); line-height: 1.7; }

/* ===== FOOTER ===== */
.footer { padding: 80px 0 0; border-top: 1px solid var(--gray-800); }
.footer__ctas {
  display: grid; gap: 32px; margin-bottom: 64px;
  grid-template-columns: 1fr;
}
@media (min-width: 768px) { .footer__ctas { grid-template-columns: 1fr 1fr; } }

.footer__cta-block { padding: 36px; border: 1px solid var(--gray-800); border-radius: 16px; }
.footer__cta-block p { font-size: 1rem; color: var(--gray-400); line-height: 1.7; margin-bottom: 20px; }
.footer__cta-btn {
  display: inline-flex; align-items: center; gap: 10px;
  font-weight: 600; font-size: 0.9rem; transition: all var(--transition);
}
.footer__cta-btn--primary { color: var(--accent); }
.footer__cta-btn--primary:hover { color: var(--accent-hover); }
.footer__cta-btn--secondary { color: var(--amber); }
.footer__cta-btn--secondary:hover { color: var(--amber-hover); }
.footer__cta-btn svg { width: 16px; height: 16px; }

.footer__bottom {
  display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center;
  gap: 24px; padding: 32px 0; border-top: 1px solid var(--gray-800);
}
.footer__links { display: flex; gap: 24px; flex-wrap: wrap; }
.footer__links a { font-size: 0.85rem; color: var(--gray-500); transition: color var(--transition); }
.footer__links a:hover { color: var(--white); }
.footer__legal { font-size: 0.8rem; color: var(--gray-600); }
.footer__legal a { color: var(--gray-500); transition: color var(--transition); }
.footer__legal a:hover { color: var(--gray-300); }

/* ===== COOKIE CONSENT ===== */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
  background: var(--bg-card); border-top: 1px solid var(--gray-800);
  transform: translateY(100%); transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 -16px 48px rgba(0,0,0,0.5);
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-banner__inner {
  max-width: 1280px; margin: 0 auto; padding: 24px;
  display: flex; flex-wrap: wrap; align-items: center; gap: 16px;
}
@media (min-width: 768px) { .cookie-banner__inner { padding: 20px 48px; } }
.cookie-banner__text { flex: 1; min-width: 240px; font-size: 0.85rem; color: var(--gray-400); line-height: 1.6; }
.cookie-banner__text a { color: var(--accent); text-decoration: underline; }
.cookie-banner__actions { display: flex; gap: 10px; flex-shrink: 0; }
.cookie-btn {
  padding: 10px 20px; font-size: 0.85rem; font-weight: 500; border-radius: 6px;
