/* ===== COOKIE SETTINGS MODAL ===== */
.cookie-modal {
  position: fixed; inset: 0; z-index: 210; display: none; align-items: center; justify-content: center;
  background: rgba(0,0,0,0.7); backdrop-filter: blur(4px);
}
